// === Tab: mySketch ===
let Shader,palette;
function setup() {
  createCanvas(windowWidth,windowHeight,WEBGL);
	pixelDensity(1);
  noStroke();
}
function draw() {
  shader(Shader);
	Shader.setUniform('pal',palette);
	Shader.setUniform('c',[cos(frameCount/256+PI/2)*0.8,cos(frameCount/256)*0.8]);
	Shader.setUniform('hue',fract(frameCount/1000));
  rect(0,0,width,height);
}
function mousePressed() {save("ColoredFrozen_Fractal");}
function preload() {
	Shader=new p5.Shader(this._renderer,`
		precision highp float;
		attribute vec3 aPosition;
		attribute vec2 aTexCoord;
		varying vec2 vTexCoord;
		void main() {
			vTexCoord=aTexCoord;
			vec4 positionVec4=vec4(aPosition,1.);
			positionVec4.xy=positionVec4.xy*2.-1.; 
			gl_Position=positionVec4;
		}
	`,`
		precision highp float;
		varying vec2 vTexCoord;
		uniform sampler2D pal;
		uniform vec2 c;
		uniform float hue;
		void main() {
			vec2 z=vec2(5.*vTexCoord.x-2.5,(5.*vTexCoord.y-2.5)*${windowHeight/windowWidth});
			int iter=100;
			for(int i=0;i<100;i++) {
				float x=(z.x+z.y)*(z.x-z.y)+c.x;
				float y=2.*z.y*z.x+c.y;
				if((x*x+y*y)>4.) {iter=i;break;}
				z.x=x;
				z.y=y;
			}
			vec3 cl1=texture2D(pal,vec2(iter==100?0.:float(iter)/100.,1)).rgb;
			vec4 p=mix(vec4(cl1.zy,vec2(-1.,2./3.)),vec4(cl1.yz,vec2(0.,-1.)),step(cl1.z,cl1.y));
			vec4 q=mix(vec4(p.xyw,cl1.x),vec4(cl1.x,p.yzx),step(p.x,cl1.r));
			vec3 cl2=vec3(hue,(q.x-min(q.w,q.y))/(q.x+1.e-10),q.x);
			gl_FragColor=vec4(cl2.z*mix(vec3(1.),clamp(abs(fract(cl2.xxx+vec3(1.,2./3.,1./3.))*6.-3.)-vec3(1.),0.,1.),cl2.y),1.);
		}
	`);
	palette=loadImage("data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAQAAAAABCAYAAAAxWXB3AAAAAXNSR0IArs4c6QAAAGRJREFUOE9jZGBg+M8ABiwMDAwcSDQyGyZHSIyQPDZzOJCsZoE6AUaDnIRDDGwUmjqYGNwrUHmQOnQxFoQc3FVIykE+AWNai7EwMPxhQOAfFLBB5gyE/uHlAeTYGM5sUEphYAAAjJafAWvSA74AAAAASUVORK5CYII=");
}

